import { expect, test, uniqueName } from "../../fixtures";

test("creating a vendor returns 201 as a draft and records an audit event", { tag: "@VEN-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");

  // Act
  const create = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  expect(create.status(), await create.text()).toBe(201);
  const vendor = await create.json();
  expect(vendor.status).toBe("draft");
  expect(vendor.name).toBe(name);
  expect(vendor.category).toBe("logistics");
  expect(vendor.contact_email).toBe("ops@acmefreight.example");

  const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(audit.status(), await audit.text()).toBe(200);
  const actions = ((await audit.json()) as { items: { action: string }[] }).items.map((e) => e.action);
  expect(actions).toContain("vendor.created");
});
